#include <stdio.h>
#include <ctype.h>

int main(void) {
    long lines = 0;
    long words = 0;
    long chars = 0;
    int in_word = 0;
    int c;

    while ((c = getc(stdin)) != EOF) {
        chars++;

        if (c == '\n') {
            lines++;
            if (in_word) {
                words++;
                in_word = 0;
            }
        } else if (c == ' ' || c == '\t' || c == '\r') {
            if (in_word) {
                words++;
                in_word = 0;
            }
        } else {
            in_word = 1;
        }
    }

    // Count the last word if the file doesn't end with whitespace
    if (in_word) {
        words++;
    }

    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
